      "rationale": "P028 directly states the possible omission from completed-export samples."
    }
  },
  "signal_basis": {
    "component_id": "C059_signal_basis",
    "value": "The investigation examines existing slow and ordinary overnight exports and tracks whether canary outcomes include increased failures or unfinished exports.",
    "scope": "Record-based comparison and canary assessment; no actual sampling omission is asserted.",
    "provenance": {
      "refs": [
        {
