      "rationale": "P005 identifies the records examined, P022 includes unfinished exports in outcome assessment, and P028 situates the possible sampling limitation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C059_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
